function makeFib() {
  const cache = {};
  return function fib(n) {
    if (n <= 1) return n;
    if (cache[n] !== undefined) return cache[n];
    const result = fib(n - 1) + fib(n - 2);
    cache[n] = result;
    return result;
  };
}
